// run with: bare lib/node_modules/auditcore/test.js
const fs = require('bare-fs')
const os = require('bare-os')
const path = require('bare-path')
const b4a = require('b4a')
const Corestore = require('corestore')
const { create_auditcore } = require('./')

let failed = 0
main().then(done)

async function main () {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'auditcore-test-'))
  const store_a = new Corestore(path.join(root, 'a'))
  const store_b = new Corestore(path.join(root, 'b'))
  const a = create_auditcore({ store: store_a.namespace('vault-audit') })
  await a.ready()
  const b = create_auditcore({ store: store_b.namespace('vault-audit'), bootstrap: a.key })
  await b.ready()
  let streams = connect(store_a, store_b)
  await a.add_writer(b.base.local.key)
  await settle([a, b], () => b.writable)
  check('a second device can write after add_writer', b.writable)
  await a.append({ type: 'test', data: { who: 'a', n: 0 } })
  await settle([a, b], () => b.length === 1)
  // both devices write while they cant see each other, so autobase has to reorder once they meet again
  streams.forEach(stream => stream.destroy())
  for (let n = 1; n <= 3; n++) {
    await a.append({ type: 'test', data: { who: 'a', n } })
    await b.append({ type: 'test', data: { who: 'b', n } })
  }
  streams = connect(store_a, store_b)
  await settle([a, b], () => a.length === 7 && b.length === 7)
  const ids_a = (await a.read()).map(entry => entry.data.who + entry.data.n)
  const ids_b = (await b.read()).map(entry => entry.data.who + entry.data.n)
  check('after writing at the same time both devices have every entry once', ids_a.length === 7 && new Set(ids_a).size === 7, ids_a.join(' '))
  check('both devices have the same entries in the same order', ids_a.join() === ids_b.join(), `a ${ids_a.join(' ')} | b ${ids_b.join(' ')}`)
  const entry = await a.get(1)
  check('every entry is { head, refs, type, data, meta }, head[0] the device that wrote it, meta.time when', entry.head[0] === b4a.toString(entry.data.who === 'a' ? a.base.local.key : b.base.local.key, 'hex') && entry.meta.time > 0 && entry.type === 'test' && Object.keys(entry.data).join() === 'who,n', JSON.stringify(entry))
  check('read(start, end) gives a part of the log', (await a.read(1, 3)).length === 2)
  check('get_by_device gives only that devices entries', (await a.get_by_device(b4a.toString(b.base.local.key, 'hex'))).length === 3)
  check('get_by_type filters by type', (await a.get_by_type('test')).length === 7 && (await a.get_by_type('nope')).length === 0)
  check('create_read_stream gives the entries', (await collect(a.create_read_stream({ start: 2, end: 5 }))).length === 3)
  // a device that appends straight to autobase with another devices id in head still shows up as itself
  await b.base.append({ head: [b4a.toString(a.base.local.key, 'hex')], type: 'test', data: { who: 'b', n: 9 }, meta: { time: 1 } })
  await settle([a, b], () => a.length === 8)
  check('a device cant write in another devices name, head[0] is always the real writer', (await a.get(7)).head[0] === b4a.toString(b.base.local.key, 'hex'))
  check('a time earlier than the entry before it becomes that time + 1', (await a.get(7)).meta.time === (await a.get(6)).meta.time + 1, `${(await a.get(6)).meta.time} -> ${(await a.get(7)).meta.time}`)
  await a.remove_writer(b.base.local.key)
  await settle([a, b], () => !b.writable)
  check('remove_writer takes the device out', !b.writable)
  // a is the only indexer left, autobase refuses to remove it, so the log has to skip that instead of breaking
  await a.remove_writer(a.base.local.key)
  await a.append({ type: 'test', data: { who: 'a', n: 10 } }).catch(() => {})
  check('removing the last indexer is skipped and the log keeps working', a.writable && a.length === 9)
  const ids_end = (await a.read()).map(entry => entry.data.who + entry.data.n)
  streams.forEach(stream => stream.destroy())
  await a.close()
  await b.close()
  await store_a.close()
  await store_b.close()
  // the log is stored by autobase, so it comes back after a restart
  const store_again = new Corestore(path.join(root, 'a'))
  const again = create_auditcore({ store: store_again.namespace('vault-audit') })
  await again.ready()
  check('the same entries come back after a restart', (await again.read()).map(entry => entry.data.who + entry.data.n).join() === ids_end.join())
  await again.close()
  await store_again.close()
  fs.rmSync(root, { recursive: true, force: true })
}

/***************************************
HELPERS
***************************************/
function check (name, ok, note = '') {
  console.log(`${ok ? 'ok' : 'not ok'} ${name}${!ok && note ? `  (${note})` : ''}`)
  if (!ok) failed++
}

function done () {
  console.log(failed ? `${failed} failed` : 'all good')
  if (failed) throw new Error('auditcore tests failed')
}

function connect (store_a, store_b) {
  const stream_a = store_a.replicate(true)
  const stream_b = store_b.replicate(false)
  stream_a.pipe(stream_b).pipe(stream_a)
  return [stream_a, stream_b]
}

// update both devices until done() or about 15 seconds passed
async function settle (logs, done) {
  for (let i = 0; i < 150; i++) {
    for (const log of logs) await log.update()
    if (done()) return
    await new Promise(resolve => setTimeout(resolve, 100))
  }
}

async function collect (stream) {
  const entries = []
  for await (const entry of stream) entries.push(entry)
  return entries
}
